    require msg(y, t);
    require ~le(t, epoch(y));
    has_lock(y) := true;
    epoch(y) := t;
}

action release_lock(x: node, y : node, t: time) = {
    require has_lock(x);
    require ~le(t, epoch(x));
    has_lock(x) := false;
    msg(y, t) := true;
}

