invariant [lock_unique] forall X:node, Y:node. (X ~= Y & has_lock(X)) -> ~has_lock(Y)

invariant [msg_sender_no_lock] forall X:node, Y:node, T:time. msg(X, Y, T) -> ~has_lock(X)

invariant [lock_at_most_one] forall X:node, Y:node. (has_lock(X) & has_lock(Y)) -> X = Y

invariant [msg_requires_sender_had_lock_before] forall X:node, Y:node, T:time. msg(X, Y, T) & X ~= Y -> true

invariant [no_self_messages_with_lock] forall X:node, T:time. msg(X, X, T) -> ~has_lock(X)

