invariant held(N1) & held(N2) -> N1 = N2

invariant transfer_msg(E, D1) & transfer_msg(E, D2) -> D1 = D2

invariant locked(E, N) -> ~held(N)

invariant transfer_msg(E, N) & locked(E, N) -> false

invariant transfer_msg(E, N1) & locked(E, N2) -> N1 = N2

invariant held(N) & transfer_msg(E, N) -> false

