invariant depends_tx(TX1, K, T3) & depends_tx(TX2, K, T3) -> TX1 = TX2
invariant precommit_tx(TX, N) -> commit_tx(TX) | TX = zero
invariant commit_tx(TX) & TX ~= zero -> precommit_tx(TX, N)

