relation showsSafeAt(I:instances, Q:quorum, B:ballot, V:value) = ((forall A:acceptor. member(A, Q) -> le(B, maxBal(A))) & 
													(exists C:ballot. ~le(B, C) & 
														(C ~= negone -> exists A:acceptor. member(A, Q) & msg_2b(I, A, C, V)) & 
