    require c ~= none;

	propCmds(c) := true;
}

action phase_1a(b:ballot) = {
    require b ~= negone;

    msg_1a(b) := true;
}

action phase_1b(a:acceptor, b:ballot) = {
    require b ~= negone;
    require msg_1a(b);
    require ~le(b, maxBal(a));

    maxBal(a) := b;
    msg_1b(I, a, b, maxVBal(I, a), maxVal(I, a)) := true;
