invariant forall B1, B2, V1, V2. chosenAt(B1, V1) & chosenAt(B2, V2) -> V1 = V2

invariant forall B, V. msg_2a(B, V) -> isSafeAtPaxos(B, V)

invariant forall A, B, V. msg_2b(A, B, V) -> msg_2a(B, V)

invariant forall B1, B2, V1, V2. le(B1, B2) & chosenAt(B1, V1) & msg_2a(B2, V2) -> V1 = V2

invariant forall B1, B2, V1, V2. le(B1, B2) & chosenAt(B1, V1) & msg_2b(A, B2, V2) -> V1 = V2

